from typing import List, Dict, Any, Optional, Tuple
from datetime import datetime, timedelta, date
import json
import asyncio
import math
from decimal import Decimal, ROUND_HALF_UP
from dataclasses import dataclass
import uuid

from ..models import (
    SplitConfiguration, SplitRecipient, SplitTransaction, 
    SplitParcela, SplitEscrow, SplitDisputa, SplitAuditoria,
    SplitReconciliacao, Transacao, VendaPDV, Usuario
)
